dtsPropsFor.Button:
/** Ember fill (default) or outlined ghost. */
  variant?: 'primary' | 'ghost';
  /** Renders an <a> instead of a <button>. */
  href?: string;
  disabled?: boolean;
  onClick?: React.MouseEventHandler;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Chip:
/** Selected: ember fill. */
  on?: boolean;
  /** Unavailable: dimmed and struck through. */
  off?: boolean;
  /** Compact header size. */
  sm?: boolean;
  /** Show the basil recommendation star. */
  star?: boolean;
  /** Tooltip explaining the recommendation. */
  starWhy?: string;
  onClick?: React.MouseEventHandler;
  title?: string;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Card:
/** Uppercase section label rendered at the top of the card. */
  label?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;

dtsPropsFor.Option:
/** Bold option title. */
  name?: React.ReactNode;
  /** Muted sub-label under the title. */
  sub?: React.ReactNode;
  /** Selected: ember ring. */
  on?: boolean;
  /** Unavailable at the current level/settings. */
  off?: boolean;
  /** Ember rationale line ('why we recommend this'). */
  why?: React.ReactNode;
  /** Faint helper line. */
  tip?: React.ReactNode;
  onClick?: React.MouseEventHandler;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Slider:
label?: React.ReactNode;
  value: number;
  onChange: (value: number) => void;
  min: number;
  max: number;
  step?: number;
  /** Unit suffix appended to the value read-out, e.g. ' %'. */
  unit?: string;
  /** Overrides the formatted value text entirely. */
  display?: React.ReactNode;
  /** Value to mark with the basil recommendation star. */
  star?: number;
  starTitle?: string;

dtsPropsFor.Stepper:
value: number;
  onChange: (value: number) => void;
  min?: number;
  max?: number;
  /** Formats the displayed value, e.g. (n) => `${n} pizzas`. */
  fmt?: (value: number) => React.ReactNode;

dtsPropsFor.StepIndicator:
/** One entry per step; used as the dot tooltip. */
  steps: string[];
  /** Zero-based index of the active step. */
  current: number;
  /** Called with the index when a reachable dot is clicked. */
  onStep?: (index: number) => void;
  className?: string;

